/** One unit, the resource it may run on now, and why it moved off its previous resource. */
export interface Assignment {
  unit: WorkUnit;
  resource: ResourceDescriptor;
  reroutedFrom?: { resourceId: string; reason: string };
}

/** An operator decision Nexus will not apply (stale, not offered, or outside the unit's authority). */
export interface WorkUnitSpec {
  id: string;
  title?: string;
  role?: AgentRole;
  prompt: string;
  dependsOn?: string[];
  requires?: WorkRequirements;
  required?: boolean;
  taskClass?: string;
  /** Operator cap on this unit's prompt context, in tokens. */
  contextBudget?: number;
  /** Paths (files or directories) a reviewed change may touch; absent declares no scope. */
  authorizedScope?: string[];
  /** Named inputs for a specialist role's contract (see SPECIALIST_CONTRACTS[role].inputRequirements). */
  inputs?: Record<string, string>;
}

/** A unit's declared scope as repository-relative path prefixes ("*" alone matches everything); anything else is refused. */
function normalizeScope(unitId: string, scope: unknown): string[] {
  if (!Array.isArray(scope) || scope.length === 0 || scope.some((p) => typeof p !== "string")) {
    throw new Error(`Work unit '${unitId}': authorizedScope must be a non-empty array of paths`);
  }
  return (scope as string[]).map((raw) => {
    const p = raw.trim().replace(/^(?:\.\/+)+/, "").replace(/\/+$/, "").replace(/\/{2,}/g, "/");
    const why =
      !p || p === "." ? "is empty (use \"*\" for the whole repository)"
      : p === "*" ? ""
      : /^(?:\/|[A-Za-z]:)/.test(p) ? "must be relative to the repository"
      : p.split(/[\\/]/).includes("..") ? "must not contain '..'"
      : /[*?[]/.test(p) ? "must not contain glob characters (a path prefix, or \"*\" alone)"
      : "";
    if (why) throw new Error(`Work unit '${unitId}': authorizedScope entry ${JSON.stringify(raw)} ${why}`);
    return p;
  });
}

export function newOperation(
  id: string,
    throw new OperationSpecError(`unknown ${scope} key '${key}'${hint ? ` (did you mean '${hint}'?)` : ""}`);
  }
}

/**
 * Validates the operator's spec before anything is created. Every rule here exists because the alternative is a
 * silent misconfiguration: an ignored key, a unit that can never be scheduled, or a limit that would be clamped.
 */
export function validateOperationSpec(spec: unknown): asserts spec is OperationSpec {
  if (!spec || typeof spec !== "object" || Array.isArray(spec)) throw new OperationSpecError("operation spec must be a JSON object");
  const s = spec as Record<string, any>;
  rejectUnknown("spec", s, SPEC_KEYS);
  if (typeof s.objective !== "string" || !s.objective.trim()) throw new OperationSpecError("operation spec needs a non-empty 'objective'");
  if (!Array.isArray(s.units) || s.units.length === 0) throw new OperationSpecError("operation spec needs a non-empty 'units' array");
  if (s.id !== undefined && (typeof s.id !== "string" || !/^[A-Za-z0-9._-]{1,160}$/.test(s.id))) {
    throw new OperationSpecError("operation spec 'id' must be 1-160 characters of letters, digits, '.', '_' or '-'");
  }
  if (s.discoverCatalog !== undefined && typeof s.discoverCatalog !== "boolean") {
    throw new OperationSpecError("operation spec 'discoverCatalog' must be true or false");
  }
  if (s.git !== undefined) {
    if (!s.git || typeof s.git !== "object" || Array.isArray(s.git)) throw new OperationSpecError("operation spec 'git' must be an object");
    rejectUnknown("git", s.git, GIT_KEYS);
    if (s.git.isolate !== undefined && typeof s.git.isolate !== "boolean") throw new OperationSpecError("operation spec 'git.isolate' must be true or false");
    if (s.git.baseRef !== undefined && typeof s.git.baseRef !== "string") throw new OperationSpecError("operation spec 'git.baseRef' must be a string");
  }
  if (s.boundaries !== undefined) {
    try {
      parseBoundaryRules(s.boundaries);
    } catch (error) {
      throw new OperationSpecError(`operation spec ${error instanceof Error ? error.message : String(error)}`);
    }
  }
