export function newOperation(
  id: string,
  objective: string,
  units: WorkUnitSpec[],
  resources: ResourceDescriptor[],
  now: number,
  policy: Partial<OperationPolicy> = {},
): DurableOperationState {
  const ids = new Set<string>();
  for (const u of units) {
    if (!u.id || ids.has(u.id)) throw new Error(`Work unit ids must be unique and non-empty (got '${u.id}')`);
    ids.add(u.id);
  }
  const byId = new Map(units.map((u) => [u.id, u]));
  for (const u of units) {
    if (u.contextBudget !== undefined && (!Number.isInteger(u.contextBudget) || u.contextBudget <= 0)) {
      throw new Error(`Work unit '${u.id}': contextBudget must be a positive integer number of tokens`);
    }
    if (u.authorizedScope !== undefined) normalizeScope(u.id, u.authorizedScope);
    if (u.inputs !== undefined) {
      const problem = specialistInputsProblem(u.inputs);
      if (problem) throw new Error(`Work unit '${u.id}': ${problem}`);
    }
    for (const d of u.dependsOn ?? []) {
      if (!ids.has(d)) throw new Error(`Work unit '${u.id}' depends on unknown unit '${d}'`);
      if (u.required !== false && byId.get(d)!.required === false) {
        throw new Error(`Required work unit '${u.id}' depends on advisory unit '${d}'; mark '${d}' required or drop the dependency`);
      }
    }
    for (const d of u.requires?.independentOf ?? []) if (!ids.has(d)) throw new Error(`Work unit '${u.id}' is independent of unknown unit '${d}'`);
  }
  if (!units.some((u) => u.required !== false)) throw new Error("An operation needs at least one required work unit");
  assertAcyclic(units);
  validateOperationPolicy(policy);
  validateResourceSlots(resources);
  const at = new Date(now).toISOString();
  return {
    schemaVersion: CURRENT_OPERATION_SCHEMA_VERSION,
    id,
    objective,
    status: "RUNNING",
    createdAt: at,
    updatedAt: at,
    units: units.map((u) => ({
      id: u.id,
      title: u.title ?? u.id,
      ...(u.role ? { role: u.role } : {}),
      prompt: u.prompt,
      dependsOn: u.dependsOn ?? [],
      requires: u.requires ?? {},
      ...(u.required === false ? { required: false } : {}),
      ...(u.taskClass ? { taskClass: u.taskClass } : {}),
      ...(u.contextBudget !== undefined ? { contextBudget: u.contextBudget } : {}),
      ...(u.authorizedScope ? { authorizedScope: normalizeScope(u.id, u.authorizedScope) } : {}),
      // A specialist unit always records its inputs (possibly none): a unit with no `inputs` field predates input
      // enforcement and is grandfathered by the executor.
      ...(u.inputs !== undefined || isSpecialistRole(u.role) ? { inputs: redactForPersistence({ ...(u.inputs ?? {}) }) } : {}),
      status: "WAITING_ON_DEPENDENCY",
      reroutes: [],
      runs: 0,
      unknownResumes: 0,
      modelsUsed: [],
    })),
    resources: resources.map((r) => ({ ...r })),
    conditions: [],
    events: [],
    policy: { ...DEFAULT_OPERATION_POLICY, ...policy },
  };
}

function assertAcyclic(units: WorkUnitSpec[]): void {
  const deps = new Map(units.map((u) => [u.id, u.dependsOn ?? []]));
  const state = new Map<string, 1 | 2>();
  const visit = (id: string, path: string[]): void => {
    if (state.get(id) === 2) return;
    if (state.get(id) === 1) throw new Error(`Work unit dependency cycle: ${[...path, id].join(" -> ")}`);
    state.set(id, 1);
    for (const d of deps.get(id) ?? []) visit(d, [...path, id]);
    state.set(id, 2);
  };
  for (const u of units) visit(u.id, []);
}
