     5	test("batch validation accepts the existing operation specification and preserves dependencies", () => {
     6	  const spec = {
     7	    id: "batch-build",
     8	    objective: "Build and verify the package",
     9	    policy: { maxConcurrentUnits: 2 },
    10	    git: { isolate: true },
    11	    units: [
    12	      { id: "implement", role: "implementer", prompt: "Implement the change", authorizedScope: ["src"] },
    13	      { id: "verify", role: "tester", prompt: "Run the checks", dependsOn: ["implement"] },
    14	    ],
    15	  };
    16	
    17	  assert.equal(validateBatchSpec(spec), spec);
    18	});
