import assert from "node:assert/strict";
import test from "node:test";
import { resolveDelegationContract, type DelegationAuthorityLayer } from "../src/core/delegation_contract.js";

const base = {
  id: "child-1",
  parentId: "parent-1",
  objective: "Inspect the requested files",
  profile: "semantic_explorer",
  inputs: {},
  authorizedScope: ["src"],
  permittedCapabilities: ["fs.read", "search.code"],
  executionMode: "transient" as const,
  requiresVerification: true,
  requiresIndependentReview: false,
};

function authority(overrides: Partial<DelegationAuthorityLayer> = {}): DelegationAuthorityLayer {
  return {
    source: "parent",
    permittedCapabilities: ["fs.read", "search.code", "proc.exec"],
    authorizedScope: ["*"],
    ...overrides,
  };
}

test("delegation authority is the intersection of parent, profile, session, workspace and task policy", () => {
  const resolved = resolveDelegationContract(base, [
    authority(),
    authority({ source: "profile", permittedCapabilities: ["fs.read", "search.code"], authorizedScope: ["src"] }),
    authority({ source: "task", permittedCapabilities: ["fs.read"], authorizedScope: ["src/lib"] }),
    authority({ source: "session", permittedCapabilities: ["fs.read", "proc.exec"], authorizedScope: ["src"] }),
    authority({ source: "workspace", permittedCapabilities: ["fs.read", "search.code"], authorizedScope: ["src"] }),
  ]);

  assert.deepEqual(resolved.permittedCapabilities, ["fs.read"]);
  assert.deepEqual(resolved.authorizedScope, ["src/lib"]);
});

test("delegation cannot request a capability outside inherited authority", () => {
  assert.throws(
    () => resolveDelegationContract({ ...base, permittedCapabilities: ["fs.read", "admin.exec"] }, [authority()]),
    /unauthorized capability.*admin.exec/,
  );
});

test("delegation cannot broaden inherited path scope", () => {
  assert.throws(
    () => resolveDelegationContract({ ...base, authorizedScope: ["src", "secrets"] }, [authority({ authorizedScope: ["src/lib"] })]),
    /outside inherited scope.*secrets/,
  );
});

test("capability identities normalize before intersection and empty policy fails closed", () => {
  const normalized = resolveDelegationContract(
    { ...base, permittedCapabilities: [" FS.READ ", "SEARCH.CODE"] },
    [authority({ permittedCapabilities: ["fs.read"] })],
  );
  assert.deepEqual(normalized.permittedCapabilities, ["fs.read"]);
  assert.deepEqual(resolveDelegationContract(base, []).permittedCapabilities, []);
  assert.deepEqual(resolveDelegationContract(base, []).authorizedScope, []);
});

